/**
 * Pre-start integrity check for the committed local Supabase configuration.
 *
 * supabase/config.toml is shared by every workflow that runs `supabase start` -- the migration
 * replay, Phase 1 release safety and Phase 2-3 release safety -- so a change to it changes all
 * three. It was generated by `supabase init` on the pinned CLI and then altered in exactly two
 * places: the project identifier, and TOTP enrolment/verification, which local GoTrue disables by
 * default and which the synthetic-marking route test needs in order to obtain a genuine AAL2
 * session rather than a mocked one.
 *
 * This asserts the file still exists, still enables TOTP, and still carries none of the settings
 * that would make the local stack diverge from the generated defaults. It prints setting names and
 * booleans only -- never a secret, a key or a full environment value.
 */
import fs from 'node:fs';
import path from 'node:path';

const configPath = path.join(process.cwd(), 'supabase', 'config.toml');

let failures = 0;
const check = (name, ok, detail = '') => {
  if (ok) {
    console.log(`  ok - ${name}${detail ? `  ${detail}` : ''}`);
  } else {
    failures += 1;
    console.log(`  FAIL - ${name}${detail ? `  ${detail}` : ''}`);
  }
};

console.log('supabase-local-config');

check('C1 supabase/config.toml exists', fs.existsSync(configPath));
if (!fs.existsSync(configPath)) process.exit(1);

const config = fs.readFileSync(configPath, 'utf8');

// The value of a key inside a named [section], so a key of the same name elsewhere cannot satisfy.
function sectionValue(section, key) {
  const start = config.indexOf(`[${section}]`);
  if (start < 0) return null;
  const rest = config.slice(start + section.length + 2);
  const end = rest.search(/^\[/m);
  const body = end < 0 ? rest : rest.slice(0, end);
  const match = body.match(new RegExp(`^\\s*${key}\\s*=\\s*(.+?)\\s*$`, 'm'));
  return match ? match[1] : null;
}

check('C2 TOTP enrolment is enabled', sectionValue('auth.mfa.totp', 'enroll_enabled') === 'true',
  `enroll_enabled=${sectionValue('auth.mfa.totp', 'enroll_enabled')}`);
check('C3 TOTP verification is enabled', sectionValue('auth.mfa.totp', 'verify_enabled') === 'true',
  `verify_enabled=${sectionValue('auth.mfa.totp', 'verify_enabled')}`);

check('C4 a stable non-sensitive local project identifier is set',
  /^project_id = "mk-fraud-readiness-score-local"$/m.test(config));

// Everything below must remain at the generated default. Each entry is (section, key, expected).
const generatedDefaults = [
  ['api', 'port', '54321'],
  ['db', 'port', '54322'],
  ['db', 'major_version', '17'],
  ['studio', 'port', '54323'],
  ['auth', 'site_url', '"http://127.0.0.1:3000"'],
  ['auth', 'jwt_expiry', '3600'],
  ['auth', 'enable_refresh_token_rotation', 'true'],
  ['auth', 'minimum_password_length', '6'],
  ['auth.mfa', 'max_enrolled_factors', '10'],
  ['auth.mfa.phone', 'enroll_enabled', 'false'],
  ['auth.mfa.phone', 'verify_enabled', 'false'],
  ['auth.email', 'enable_signup', 'true'],
  ['auth.sms', 'enable_signup', 'false'],
  ['storage', 'file_size_limit', '"50MiB"'],
  ['realtime', 'enabled', 'true'],
  ['analytics', 'enabled', 'true'],
];
for (const [section, key, expected] of generatedDefaults) {
  const actual = sectionValue(section, key);
  check(`C5 ${section}.${key} remains the generated default`, actual === expected,
    `expected=${expected} actual=${actual}`);
}

// No credential-shaped value may be committed here. The generated file references secrets only as
// env() indirections, never as literals.
const literalSecret = config
  .split('\n')
  .filter((line) => !line.trim().startsWith('#'))
  .find((line) => /(secret|password|token|api_key|service_role)\s*=\s*"(?!env\()[^"]{8,}"/i.test(line));
check('C6 no literal secret, password or key is committed', !literalSecret,
  literalSecret ? `offending key: ${literalSecret.split('=')[0].trim()}` : '');

// Only TOTP may be enabled. Any other MFA mechanism this CLI emits must stay disabled, and a
// mechanism it does not emit must not have been added by hand.
const mfaSections = [...config.matchAll(/^\[auth\.mfa\.([a-z_]+)\]/gm)].map((m) => m[1]);
check('C7 only TOTP and phone MFA sections are present, as generated',
  mfaSections.length === 2 && mfaSections.includes('totp') && mfaSections.includes('phone'),
  `sections=${mfaSections.join(',')}`);
for (const section of mfaSections.filter((s) => s !== 'totp')) {
  check(`C8 auth.mfa.${section} remains disabled`,
    sectionValue(`auth.mfa.${section}`, 'enroll_enabled') === 'false'
      && sectionValue(`auth.mfa.${section}`, 'verify_enabled') === 'false',
    `enroll=${sectionValue(`auth.mfa.${section}`, 'enroll_enabled')} verify=${sectionValue(`auth.mfa.${section}`, 'verify_enabled')}`);
}

console.log('');
console.log(failures === 0
  ? 'supabase-local-config: all checks passed'
  : `supabase-local-config: ${failures} check(s) failed`);
process.exit(failures === 0 ? 0 : 1);
